import { installLegacyRevision } from '../fixtures/install-legacy-revision.js';
import assert from "node:assert/strict";
import { readAgentPluginActivations, recordBundledAgentPluginIfAbsent, setAgentPluginActivation } from "../test-support.js";
import { createHash } from "node:crypto";
import { chmod, mkdtemp, readFile, readdir, stat, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "../legacy-test.js";

import { forceRemove } from "../fixtures/force-remove.js";
import { ACTIVATIONS_FILENAME } from "../../activation.js";
import { installAgentPlugin } from "../test-support.js";
import { type AgentPluginArchiveEntry, type AgentPluginArchiveReaderPort } from "../../install.js";
import { resolveAgentPluginLayout } from "../test-support.js";

import { previewAgentPluginUninstall, uninstallAgentPlugin } from "../test-support.js";
import { AgentPluginChangedSincePreviewError, AgentPluginNotFoundError, AgentPluginNotUninstallableError } from "../../uninstall.js";

/**
 * @file `uninstallAgentPlugin()` — the RED/GREEN proof this domain's uninstall was missing entirely
 * before this dispatch. No `origin: "operator-installed"` Agent Plugin can exist through any real
 * flow yet (there is no install-from-marketplace surface, only `install-from-url.ts`'s dev/admin
 * path) — every test below that needs one CONSTRUCTS it directly via `installAgentPlugin` plus
 * `setAgentPluginActivation`, exactly the way a real operator install would leave the workspace.
 */

const WORKSPACE_ID = "11111111-1111-4111-8111-111111111111";

function reader(entries: readonly AgentPluginArchiveEntry[]): AgentPluginArchiveReaderPort {
  return {
    async *entries() {
      yield* entries;
    },
  };
}

function fileEntry(entryPath: string, content: string): AgentPluginArchiveEntry {
  const bytes = Buffer.from(content, "utf8");
  return {
    kind: "file",
    entryPath,
    declaredSize: bytes.byteLength,
    executable: false,
    async *openReadStream() {
      yield bytes;
    },
  } as AgentPluginArchiveEntry;
}

async function freshLayout() {
  const cwd = await mkdtemp(path.join(tmpdir(), "host-agent-plugin-uninstall-test-"));
  const instanceLayout = resolveAgentPluginLayout({ cwd, env: {} });
  return { cwd, instanceLayout, workspaceLayout: instanceLayout.forWorkspace({ workspaceId: WORKSPACE_ID }) };
}

/** Installs a real package via `installAgentPlugin` — the same mechanism a real install-from-url
 *  flow uses — so every "operator-installed" test below exercises the real on-disk shape, not a
 *  hand-rolled fixture. */
async function installTestPackage(instanceLayout: ReturnType<typeof resolveAgentPluginLayout>, pluginId: string, archiveLabel: string) {
  const manifest = JSON.stringify({ $schema: "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json", name: pluginId, version: "1.0.0" });
  const archive = new Uint8Array(Buffer.from(archiveLabel));
  const digest = createHash("sha256").update(archive).digest("hex");
  return installAgentPlugin({
    archive,
    expectedSha256: digest,
    archiveReader: reader([fileEntry("plugin.json", manifest), fileEntry(`skills/${pluginId}/SKILL.md`, `# ${pluginId}\n`)]),
    layout: instanceLayout,
    workspaceId: WORKSPACE_ID,
  });
}

test("refuses an unknown plugin id with AgentPluginNotFoundError", async () => {
  const { cwd, instanceLayout } = await freshLayout();
  try {
    await assert.rejects(
      () => uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "does-not-exist" }),
      (error: unknown) => error instanceof AgentPluginNotFoundError && /not installed/.test(error.message),
    );
  } finally {
    await forceRemove(cwd);
  }
});

test("refuses a bundled plugin with AgentPluginNotUninstallableError, naming the disable alternative — and removes nothing", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const installed = await installTestPackage(instanceLayout, "site-compliance", "archive-bundled");
    await recordBundledAgentPluginIfAbsent({ workspaceRoot: workspaceLayout.root, pluginId: "site-compliance" });

    await assert.rejects(
      () => uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "site-compliance" }),
      (error: unknown) =>
        error instanceof AgentPluginNotUninstallableError &&
        /bundled/i.test(error.message) &&
        // Since a1abe2bb the assistant CAN disable one itself — the refusal must say how, not send
        // the model to a human for something it can do.
        /disable it through the host's activation control/.test(error.message) &&
        !/no assistant tool wraps/.test(error.message),
    );

    const stillPublished = await stat(installed.packageRoot);
    assert.equal(stillPublished.isDirectory(), true, "a refused uninstall must not touch the on-disk package");

    const activations = await readAgentPluginActivations(workspaceLayout.root);
    assert.equal(activations.plugins["site-compliance"]?.origin, "bundled", "the bundled activation record must survive a refusal");
  } finally {
    await forceRemove(cwd);
  }
});

// t91 R4: a present-but-malformed entry for THIS plugin means its provenance is undetermined — the same "undetermined
// means refuse" rule the per-call gate applies (F1.1). Uninstalling anyway would remove a bundled plugin that the
// next boot silently re-seeds.
for (const [label, entry] of [
  ["a non-object entry", '"bundled"'],
  ["an entry with a non-boolean 'enabled'", '{"enabled":"yes","origin":"operator-installed"}'],
] as const) {
  test(`t91 R4: ${label} for the plugin refuses preview AND uninstall — nothing removed, file bytes unchanged`, async () => {
    const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
    try {
      const installed = await installTestPackage(instanceLayout, "op-plugin", `archive-malformed-${label}`);
      const activationsPath = path.join(workspaceLayout.root, ACTIVATIONS_FILENAME);
      const bytes = `{"schemaVersion":1,"plugins":{"op-plugin":${entry}}}`;
      await writeFile(activationsPath, bytes);
      const req = { layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "op-plugin" };
      const refusal = (error: unknown) =>
        error instanceof AgentPluginNotUninstallableError &&
        error.message ===
          "Agent Plugin 'op-plugin' cannot be uninstalled: its entry in this workspace's activation record is malformed, so " +
            "whether it is bundled with the host (and would be re-seeded on the next boot) cannot be established. Nothing was " +
            "removed. Tell the user an operator has to repair that entry in activations.json first; until then this " +
            "plugin's tool calls and plugin-pinned runs are refused.";

      await assert.rejects(() => previewAgentPluginUninstall(req), refusal);
      await assert.rejects(() => uninstallAgentPlugin(req), refusal);

      assert.equal((await stat(installed.packageRoot)).isDirectory(), true);
      assert.equal(await readFile(activationsPath, "utf8"), bytes);
    } finally {
      await forceRemove(cwd);
    }
  });
}

test("t91 R4: a malformed entry for a DIFFERENT plugin does not block uninstalling this one, and survives the delete", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const installed = await installTestPackage(instanceLayout, "op-plugin", "archive-malformed-sibling");
    const activationsPath = path.join(workspaceLayout.root, ACTIVATIONS_FILENAME);
    await writeFile(
      activationsPath,
      '{"schemaVersion":1,"plugins":{"other-plugin":"garbage","op-plugin":{"enabled":true,"origin":"operator-installed"}}}',
    );

    const result = await uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "op-plugin" });

    assert.deepEqual(result.removedDigests, [installed.archiveDigest]);
    await assert.rejects(() => stat(installed.packageRoot), { code: "ENOENT" });
    assert.deepEqual(JSON.parse(await readFile(activationsPath, "utf8")).plugins, { "other-plugin": "garbage" });
  } finally {
    await forceRemove(cwd);
  }
});

test("uninstalls an operator-installed plugin: removes the package root and deletes (not tombstones) its activation record", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const installed = await installTestPackage(instanceLayout, "my-custom-plugin", "archive-operator-installed");
    // A real operator install leaves NO activation record until explicitly toggled — but this test
    // also proves the delete-not-tombstone decision, so it toggles first (mirroring
    // AGENT_PLUGIN_SET_ENABLED) to prove an EXISTING operator-installed record is fully removed, not
    // merely flipped.
    await setAgentPluginActivation({ workspaceRoot: workspaceLayout.root, pluginId: "my-custom-plugin", enabled: false, actor: "op-1" });

    const result = await uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "my-custom-plugin" });

    assert.equal(result.pluginId, "my-custom-plugin");
    assert.deepEqual(result.removedDigests, [installed.archiveDigest]);

    await assert.rejects(() => stat(installed.packageRoot), "the package root must actually be gone from disk");
    assert.deepEqual((await readdir(workspaceLayout.pluginRootDir({ pluginId: "my-custom-plugin" }))).sort(), ["data", "memory"], "only preserved state may remain; the package tree must be removed");

    const activations = await readAgentPluginActivations(workspaceLayout.root);
    assert.equal(
      "my-custom-plugin" in activations.plugins,
      false,
      "the activation record must be DELETED, not left behind as a disabled tombstone — a future " +
        "reinstall of the same id must start fresh (active by default), not inherit a stale disable",
    );
  } finally {
    await forceRemove(cwd);
  }
});

test("uninstalls an operator-installed plugin that was NEVER explicitly toggled (no activation record at all)", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const installed = await installTestPackage(instanceLayout, "never-toggled", "archive-never-toggled");

    const activationsBefore = await readAgentPluginActivations(workspaceLayout.root);
    assert.equal("never-toggled" in activationsBefore.plugins, false, "sanity: a fresh install has no activation record yet");

    const result = await uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "never-toggled" });
    assert.deepEqual(result.removedDigests, [installed.archiveDigest]);
    await assert.rejects(() => stat(installed.packageRoot));
  } finally {
    await forceRemove(cwd);
  }
});

test("removing a frozen (read-only, 0o555) published package root does not throw EACCES", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const installed = await installTestPackage(instanceLayout, "frozen-check", "archive-frozen-check");
    const rootMode = (await stat(installed.packageRoot)).mode & 0o777;
    assert.equal(rootMode, 0o555, "sanity: install.ts really does freeze the package root read-only");

    await uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "frozen-check" });
    await assert.rejects(() => stat(installed.packageRoot));
  } finally {
    await forceRemove(cwd);
  }
});

test("a failed uninstall puts every staged package tree back — no digest is left half-deleted", {
  skip: process.getuid?.() === 0,
}, async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const first = await installTestPackage(instanceLayout, "multi-digest", "archive-multi-digest-a");
    const second = await installLegacyRevision({ packagesDir: workspaceLayout.pluginPackagesDir({ pluginId: "multi-digest" }), install: () => installTestPackage(instanceLayout, "multi-digest", "archive-multi-digest-b") });
    await setAgentPluginActivation({ workspaceRoot: workspaceLayout.root, pluginId: "multi-digest", enabled: true, actor: "op-1" });

    // Freeze the workspace ROOT only. `<pluginId>/package/sha256/` keeps its own mode, so every digest can be
    // staged successfully and the failure lands on the activation record's write-temp-then-rename —
    // the one ordering under which "did the rollback actually run?" is a real question. A rollback
    // that only ever fires on the FIRST digest (i.e. before anything is staged) is a no-op, and the
    // two assertions below it would pass for an implementation that never staged anything at all.
    await chmod(workspaceLayout.root, 0o555);
    let failure: unknown = null;
    try {
      await uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "multi-digest" });
    } catch (error) {
      failure = error;
    } finally {
      await chmod(workspaceLayout.root, 0o700);
    }

    assert.notEqual(failure, null, "uninstall must reject when the activation record cannot be rewritten");
    assert.match(
      failure instanceof Error ? failure.message : String(failure),
      new RegExp(ACTIVATIONS_FILENAME.replace(".", "\\.")),
      "the failure must come from the activation-record write, proving every package tree was already staged " +
        "aside — an EACCES naming a package root instead would mean staging never got off the ground",
    );

    assert.equal((await stat(first.packageRoot)).isDirectory(), true, "a failed uninstall must not leave the first digest deleted");
    assert.equal((await stat(second.packageRoot)).isDirectory(), true, "a failed uninstall must not leave the second digest deleted");
    assert.equal(
      (await stat(first.packageRoot)).mode & 0o777,
      0o555,
      "staging has to unfreeze a package root to rename it; a restored tree must be frozen again, not left writable",
    );
    assert.deepEqual(
      (await readdir(workspaceLayout.pluginPackagesDir({ pluginId: "multi-digest" }))).sort(),
      [first.archiveDigest, second.archiveDigest].sort(),
      "the rollback must restore the original digest names and leave no staged directory behind",
    );

    const activations = await readAgentPluginActivations(workspaceLayout.root);
    assert.equal(activations.plugins["multi-digest"]?.enabled, true, "the activation record must survive, so it still describes real bytes");
  } finally {
    await forceRemove(cwd);
  }
});

test("TENANT ISOLATION: uninstalling in one workspace never touches another workspace's own copy of the same plugin id", async () => {
  const cwd = await mkdtemp(path.join(tmpdir(), "host-agent-plugin-uninstall-test-"));
  try {
    const instanceLayout = resolveAgentPluginLayout({ cwd, env: {} });
    const otherWorkspaceId = "22222222-2222-4222-8222-222222222222";

    const manifest = JSON.stringify({ $schema: "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json", name: "shared-name", version: "1.0.0" });
    const archive = new Uint8Array(Buffer.from("archive-shared-across-two-workspaces"));
    const digest = createHash("sha256").update(archive).digest("hex");
    const archiveReader = reader([fileEntry("plugin.json", manifest), fileEntry("skills/shared-name/SKILL.md", "# Shared\n")]);

    const installedMine = await installAgentPlugin({ archive, expectedSha256: digest, archiveReader, layout: instanceLayout, workspaceId: WORKSPACE_ID });
    const installedOther = await installAgentPlugin({ archive, expectedSha256: digest, archiveReader, layout: instanceLayout, workspaceId: otherWorkspaceId });

    await uninstallAgentPlugin({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "shared-name" });

    await assert.rejects(() => stat(installedMine.packageRoot));
    const otherStillThere = await stat(installedOther.packageRoot);
    assert.equal(otherStillThere.isDirectory(), true, "the other workspace's own copy must survive untouched");
  } finally {
    await forceRemove(cwd);
  }
});

test("previewAgentPluginUninstall names what would be removed — id, versions, digests — without removing anything or carrying a host path", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const installed = await installTestPackage(instanceLayout, "preview-me", "archive-preview");
    await setAgentPluginActivation({ workspaceRoot: workspaceLayout.root, pluginId: "preview-me", enabled: true, actor: "op-1" });

    const preview = await previewAgentPluginUninstall({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "preview-me" });

    assert.deepEqual(preview, { pluginId: "preview-me", versions: ["1.0.0"], archiveDigests: [installed.archiveDigest] });
    assert.equal(JSON.stringify(preview).includes(cwd), false, "the preview feeds a confirmation dialog; it must carry no host path");
    assert.equal((await stat(installed.packageRoot)).isDirectory(), true, "a preview must not remove the package");
    const activations = await readAgentPluginActivations(workspaceLayout.root);
    assert.equal(activations.plugins["preview-me"]?.enabled, true, "a preview must not touch the activation record");
  } finally {
    await forceRemove(cwd);
  }
});

test("previewAgentPluginUninstall refuses exactly what uninstallAgentPlugin refuses — an unknown id and a bundled plugin", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    await installTestPackage(instanceLayout, "site-compliance", "archive-preview-bundled");
    await recordBundledAgentPluginIfAbsent({ workspaceRoot: workspaceLayout.root, pluginId: "site-compliance" });

    await assert.rejects(
      () => previewAgentPluginUninstall({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "does-not-exist" }),
      AgentPluginNotFoundError,
    );
    await assert.rejects(
      () => previewAgentPluginUninstall({ layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "site-compliance" }),
      AgentPluginNotUninstallableError,
    );
  } finally {
    await forceRemove(cwd);
  }
});

// ---------------------------------------------------------------------------
// t91 F2.2 — a confirmed preview binds the uninstall to what was resolved for the dialog
// ---------------------------------------------------------------------------

test("a confirmed preview refuses — removing nothing — when an archive for the same id was installed after it was taken", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const first = await installTestPackage(instanceLayout, "changed-plugin", "archive-changed-a");
    await setAgentPluginActivation({ workspaceRoot: workspaceLayout.root, pluginId: "changed-plugin", enabled: false, actor: "op-1" });
    const req = { layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "changed-plugin" };
    const preview = await previewAgentPluginUninstall(req);
    const second = await installTestPackage(instanceLayout, "changed-plugin", "archive-changed-b");

    await assert.rejects(
      () => uninstallAgentPlugin(req, { confirmedPreview: preview }),
      (error: unknown) =>
        error instanceof AgentPluginChangedSincePreviewError &&
        error.message ===
          `Agent Plugin 'changed-plugin' changed after its uninstall was previewed (previewed archive digests: ${first.archiveDigest}; ` +
            `installed now: ${second.archiveDigest}) — nothing was removed`,
    );

    await assert.rejects(stat(first.packageRoot), { code: "ENOENT" });
    assert.equal((await stat(second.packageRoot)).isDirectory(), true);
    assert.deepEqual(await readdir(workspaceLayout.pluginPackagesDir({ pluginId: "changed-plugin" })), [second.archiveDigest]);
    const activations = await readAgentPluginActivations(workspaceLayout.root);
    assert.equal(activations.plugins["changed-plugin"]?.enabled, false);
  } finally {
    await forceRemove(cwd);
  }
});

test("a confirmed preview refuses when one of its previewed archives was removed before the answer", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const first = await installTestPackage(instanceLayout, "shrunk-plugin", "archive-shrunk-a");
    // Install now prunes superseded revisions (1c5d476f), so two coexisting archives are the legacy store.
    const second = await installLegacyRevision({ packagesDir: workspaceLayout.pluginPackagesDir({ pluginId: "shrunk-plugin" }), install: () => installTestPackage(instanceLayout, "shrunk-plugin", "archive-shrunk-b") });
    const req = { layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "shrunk-plugin" };
    const preview = await previewAgentPluginUninstall(req);
    await forceRemove(second.packageRoot);

    await assert.rejects(() => uninstallAgentPlugin(req, { confirmedPreview: preview }), AgentPluginChangedSincePreviewError);

    assert.equal((await stat(first.packageRoot)).isDirectory(), true);
  } finally {
    await forceRemove(cwd);
  }
});

test("an unchanged confirmed preview uninstalls normally", async () => {
  const { cwd, instanceLayout, workspaceLayout } = await freshLayout();
  try {
    const installed = await installTestPackage(instanceLayout, "unchanged-plugin", "archive-unchanged");
    const req = { layout: instanceLayout, workspaceId: WORKSPACE_ID, pluginId: "unchanged-plugin" };
    const preview = await previewAgentPluginUninstall(req);

    const result = await uninstallAgentPlugin(req, { confirmedPreview: preview });

    assert.deepEqual(result, { pluginId: "unchanged-plugin", removedDigests: [installed.archiveDigest] });
    await assert.rejects(() => stat(installed.packageRoot));
  } finally {
    await forceRemove(cwd);
  }
});

src/admin-surfaces/__tests__/admin-surfa.source:
/**
 * @file Security pins for admin surfaces (phase A): path containment, the sandbox attribute, the CSP
 * string and its extra-source validation, the host-page message gate, the server-side dispatcher's
 * refusals, the surface client's trust rules and the bootstrap's no-store/expiry contract.
 */
import { mkdtemp, mkdir, rm, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, test, vi } from 'vitest';
import { PackagePathViolation } from '../../lifecycle/package-paths.js';
import { readTrustedPluginFile } from '../../lifecycle/__tests__/test-support.js';
import {
  adminSurfaceBootstrapHeaders, adminSurfaceFrameAttributes, createAdminSurfaceActionDispatcher, createAdminSurfaceBootstrap, createAdminSurfaceMount, parseAdminSurfacesFile, readAdminSurfaceFile, validateAdminSurfaceMessage, type AdminSurfaceDescriptor, type AdminSurfaceMessageEvent, type AdminSurfaceMountRecord,
} from '../index.js';
import { AdminSurfaceActionError } from '../action-dispatcher.js';
import { adminSurfaceContentSecurityPolicy, adminSurfaceFileHeaders, isAdminSurfaceBootstrapCurrent } from '../sandbox.js';
import { createAdminSurfaceClient, type AdminSurfaceIncomingMessage } from '../surface-client.js';

const input = { type: 'object', properties: { name: { type: 'string', maxLength: 20 } }, required: ['name'] } as const;
const surface = (overrides: Record<string, unknown> = {}) => ({ id: 'settings', title: 'Settings', entry: 'surface/index.html', files: ['surface/app.mjs'], actions: [{ name: 'save', input }], ...overrides });
const file = (surfaces: unknown[]) => JSON.stringify({ schemaVersion: 1, surfaces });
function parseOne(overrides: Record<string, unknown> = {}): AdminSurfaceDescriptor {
  const parsed = parseAdminSurfacesFile({ raw: file([surface(overrides)]) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0]!;
}
const reasonFor = (overrides: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: file([surface(overrides)]) });
  return parsed.ok ? 'accepted' : parsed.reason;
};

describe('contained paths', () => {
  test.each(['../index.html', '/abs/index.html', 'surface\\index.html', 'surface//index.html', './index.html', 'surface/../index.html', '%2e%2e/index.html', '.hidden/index.html', 'index.htm'])('entry %j is refused', (entry) => {
    expect(reasonFor({ entry })).toBe('surfaces[0].entry must be a plain relative path ending in .html');
  });
  test.each(['../app.mjs', '/app.mjs', 'app.exe', 'surface/../../app.mjs', 'app.html'])('file %j is refused', (bad) => {
    expect(reasonFor({ files: [bad] })).toBe('surfaces[0].files[0] must be a plain relative path ending in .mjs, .js, .css, .json');
  });
  test('only the entry and declared files are read; anything else is refused without I/O', async () => {
    const reads: string[] = [];
    const loaded = { plugin: { pluginId: 'acme', packageRoot: '/p' }, descriptor: parseOne() };
    const readFile = async ({ filename }: { readonly filename: string }) => { reads.push(filename); return 'body'; };
    expect(await readAdminSurfaceFile({ surface: loaded, path: 'surface/../secret.json', readFile })).toEqual({ ok: false, reason: 'not-declared' });
    expect(await readAdminSurfaceFile({ surface: loaded, path: 'plugin.json', readFile })).toEqual({ ok: false, reason: 'not-declared' });
    expect(reads).toEqual([]);
    expect(await readAdminSurfaceFile({ surface: loaded, path: 'surface/app.mjs', readFile })).toMatchObject({ ok: true, body: 'body' });
    expect(reads).toEqual(['surface/app.mjs']);
  });
});

test('a declared file that is a symlink out of the plugin root is refused on disk', async () => {
  const base = await mkdtemp(path.join(tmpdir(), 'admin-surface-escape-'));
  try {
    const root = path.join(base, 'plugin');
    await mkdir(path.join(root, 'surface'), { recursive: true });
    await writeFile(path.join(base, 'outside.mjs'), 'export const secret = 1;');
    await symlink(path.join(base, 'outside.mjs'), path.join(root, 'surface/app.mjs'));
    const loaded = { plugin: { pluginId: 'acme', packageRoot: root }, descriptor: parseOne() };
    await expect(readAdminSurfaceFile({ surface: loaded, path: 'surface/app.mjs', readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename) })).rejects.toBeInstanceOf(PackagePathViolation);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

describe('sandboxed iframe contract', () => {
  test('sandbox is exactly allow-scripts, never allow-same-origin', () => {
    const attributes = adminSurfaceFrameAttributes({ src: '/s/index.html', title: 'Settings' });
    expect(attributes).toEqual({ src: '/s/index.html', title: 'Settings', sandbox: 'allow-scripts', referrerPolicy: 'no-referrer' });
  });
  test('the default CSP is strict and closes network and framing', () => {
    expect(adminSurfaceContentSecurityPolicy({ descriptor: parseOne() })).toBe(
      "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'; frame-ancestors 'self'; sandbox allow-scripts",
    );
  });
  test('declared, validated origins extend only their own directive', () => {
    const descriptor = parseOne({ csp: { 'connect-src': ['https://api.example.com'], 'script-src': ['https://cdn.example.com:8443'] } });
    expect(adminSurfaceContentSecurityPolicy({ descriptor })).toBe(
      "default-src 'none'; script-src 'self' https://cdn.example.com:8443; style-src 'self'; img-src 'self'; font-src 'self'; connect-src https://api.example.com; frame-src 'none'; form-action 'none'; base-uri 'none'; frame-ancestors 'self'; sandbox allow-scripts",
    );
  });
  test.each([
    'http://api.example.com', 'https://*.example.com', '*', "'unsafe-inline'", "'unsafe-eval'", 'https://api.example.com/path',
    'https://api.example.com:443', 'https://user@api.example.com', 'https://127.0.0.1', 'data:', 'https://API.example.com',
    'https://api.example.com; script-src *', 'https://api.example.com ', 'blob:',
  ])('extra CSP source %j refuses the file', (source) => {
    expect(reasonFor({ csp: { 'connect-src': [source] } })).toBe("surfaces[0].csp['connect-src'] may only list bare https origins (no wildcards, paths or keywords)");
  });
  test.each(['default-src', 'sandbox', 'frame-ancestors', 'form-action', '__proto__'])('directive %j cannot be extended', (directive) => {
    expect(reasonFor({ csp: JSON.parse(`{${JSON.stringify(directive)}:["https://a.example.com"]}`) })).toBe(`surfaces[0].csp may not extend '${directive}'`);
  });
  test('served script files get the CSP, nosniff and a credential-free CORS grant; html gets no CORS', () => {
    const descriptor = parseOne();
    const csp = adminSurfaceContentSecurityPolicy({ descriptor });
    expect(adminSurfaceFileHeaders({ descriptor, path: 'surface/app.mjs' })).toEqual({
      'Content-Type': 'text/javascript; charset=utf-8', 'Content-Security-Policy': csp, 'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'no-referrer', 'Cache-Control': 'no-cache', 'Access-Control-Allow-Origin': '*',
    });
    expect(adminSurfaceFileHeaders({ descriptor, path: 'surface/index.html' })).not.toHaveProperty('Access-Control-Allow-Origin');
  });
});

describe('action schemas are a closed subset', () => {
  test.each([
    [{ type: 'string', pattern: '.*' }, "surfaces[0].actions[0].input uses unsupported keyword 'pattern'"],
    [{ type: 'object', additionalProperties: true }, 'surfaces[0].actions[0].input additionalProperties may only be false (objects are closed)'],
    [{ properties: {} }, 'surfaces[0].actions[0].input must declare a supported type'],
    [{ type: 'object', required: ['missing'] }, 'surfaces[0].actions[0].input required must list declared properties'],
  ])('declaration %j is refused', (schema, reason) => {
    expect(reasonFor({ actions: [{ name: 'save', input: schema }] })).toBe(reason);
  });
});

describe('host-page message gate', () => {
  const frame = {};
  const mount: AdminSurfaceMountRecord = { mountId: 'nonce-1', frame, descriptor: parseOne() };
  const request = (overrides: Record<string, unknown> = {}) => ({ protocol: 'jini.admin-surface', version: 1, kind: 'action-request', mountId: 'nonce-1', requestId: 'r1', action: 'save', payload: { name: 'x' }, ...overrides });
  const event = (overrides: Partial<AdminSurfaceMessageEvent> = {}, data = request()): AdminSurfaceMessageEvent => ({ origin: 'null', source: frame, data, ...overrides });

  test('a well-formed request from this mount passes', () => {
    expect(validateAdminSurfaceMessage({ event: event(), mount })).toEqual({ ok: true, request: request() });
  });
  test('a different origin is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({ origin: 'https://evil.example.com' }), mount })).toEqual({ ok: false, ignored: 'origin-mismatch' });
  });
  test('a mount record cannot widen the accepted origin beyond "null"', () => {
    // Malformed input on purpose: a record carrying an extra origin field the gate must ignore.
    const widened = { ...mount, expectedOrigin: 'https://surfaces.example.com' };
    expect(validateAdminSurfaceMessage({ event: event({ origin: 'https://surfaces.example.com' }), mount: widened })).toEqual({ ok: false, ignored: 'origin-mismatch' });
  });
  test('another sandboxed frame (same "null" origin, different window) is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({ source: {} }), mount })).toEqual({ ok: false, ignored: 'source-mismatch' });
  });
  test('a wrong mount nonce is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({}, request({ mountId: 'nonce-2' })), mount })).toEqual({ ok: false, ignored: 'mount-mismatch' });
  });
  test('a malformed envelope is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({}, request({ requestId: 'has space' })), mount })).toEqual({ ok: false, ignored: 'not-an-action-request' });
  });
  test('an undeclared action is refused with a response', () => {
    const verdict = validateAdminSurfaceMessage({ event: event({}, request({ action: 'delete-everything' })), mount });
    expect(verdict).toMatchObject({ ok: false, refused: 'action-undeclared', response: { kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: false, error: { code: 'action-undeclared' } } });
  });
  test('a payload outside the schema is refused without echoing the value', () => {
    const verdict = validateAdminSurfaceMessage({ event: event({}, request({ payload: { name: 'x', token: 'SECRET-VALUE' } })), mount });
    expect(verdict).toMatchObject({ ok: false, refused: 'invalid-payload' });
    expect(JSON.stringify(verdict)).not.toContain('SECRET-VALUE');
  });
  test('an oversized payload is refused', () => {
    const verdict = validateAdminSurfaceMessage({ event: event({}, request({ payload: { name: 'x'.repeat(70_000) } })), mount });
    expect(verdict).toMatchObject({ ok: false, refused: 'invalid-payload', response: { error: { message: 'The request is too large.' } } });
  });
});

describe('server-side dispatcher', () => {
  const descriptor = parseOne({ actions: [{ name: 'save', input, result: { type: 'object', properties: { saved: { type: 'boolean' } }, required: ['saved'] } }] });
  test('an undeclared action is refused even when a handler exists for it', async () => {
    const handler = vi.fn(async () => ({ saved: true }));
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: handler, purge: handler } });
    expect(await dispatch({ action: 'purge', payload: {}, context: {} })).toEqual({ ok: false, error: { code: 'action-undeclared', message: 'This surface did not declare that action.', retryable: false } });
    expect(handler).not.toHaveBeenCalled();
  });
  test.each(['__proto__', 'constructor', 'toString'])('prototype key %j never resolves a handler', async (action) => {
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor: { id: 's', actions: [{ name: action, input }] }, handlers: {} });
    expect(await dispatch({ action, payload: { name: 'x' }, context: {} })).toMatchObject({ ok: false, error: { code: 'action-unavailable' } });
  });
  test('an oversized payload is refused server-side too and never reaches the handler', async () => {
    const handler = vi.fn(async () => ({ saved: true }));
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: handler } });
    expect(await dispatch({ action: 'save', payload: { name: 'x'.repeat(70_000) }, context: {} }))
      .toEqual({ ok: false, error: { code: 'invalid-payload', message: 'The request is too large.', retryable: false } });
    expect(handler).not.toHaveBeenCalled();
  });
  test('an invalid payload never reaches the handler', async () => {
    const handler = vi.fn(async () => ({ saved: true }));
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: handler } });
    expect(await dispatch({ action: 'save', payload: { name: 42 }, context: {} })).toMatchObject({ ok: false, error: { code: 'invalid-payload', message: "The request does not match the action's input: $.name must be a string." } });
    expect(handler).not.toHaveBeenCalled();
  });
  test('a handler throw is reported to the host but never leaks to the surface', async () => {
    const heard: unknown[] = [];
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: async () => { throw new Error('db password=hunter2'); } } }, { onHandlerError: ({ error }) => heard.push(error) });
    const outcome = await dispatch({ action: 'save', payload: { name: 'x' }, context: {} });
    expect(outcome).toEqual({ ok: false, error: { code: 'action-failed', message: 'The action failed. Try again; if it keeps failing, check the server log.', retryable: true } });
    expect(heard).toHaveLength(1);
  });
  test('an AdminSurfaceActionError carries its surface-safe code and message', async () => {
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: async () => { throw new AdminSurfaceActionError({ code: 'reconnect-required', message: 'Reconnect the account.' }, { retryable: false }); } } });
    expect(await dispatch({ action: 'save', payload: { name: 'x' }, context: {} })).toEqual({ ok: false, error: { code: 'reconnect-required', message: 'Reconnect the account.', retryable: false } });
  });
  test('a result outside the declared result schema is refused', async () => {
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: async () => ({ saved: true, accessToken: 'SECRET' }) } });
    expect(await dispatch({ action: 'save', payload: { name: 'x' }, context: {} })).toEqual({ ok: false, error: { code: 'invalid-result', message: 'The host returned a result this surface did not declare.', retryable: false } });
  });
});

describe('surface client trust rules', () => {
  afterEach(() => vi.useRealTimers());
  function harness() {
    const parent = { posted: [] as Array<{ message: unknown; targetOrigin: string }>, postMessage(message: unknown, targetOrigin: string) { this.posted.push({ message, targetOrigin }); } };
    let deliver: (event: AdminSurfaceIncomingMessage) => void = () => {};
    const client = createAdminSurfaceClient({ parent, listen: (handler) => { deliver = handler; return () => { deliver = () => {}; }; } }, { timeoutMs: 1000, nowMs: () => 5_000 });
    const init = (overrides: Partial<AdminSurfaceIncomingMessage> = {}, data: Record<string, unknown> = {}) => deliver({ origin: 'https://host.example.com', source: parent, data: { protocol: 'jini.admin-surface', version: 1, kind: 'init', mountId: 'nonce-1', ...data }, ...overrides });
    const respond = (overrides: Partial<AdminSurfaceIncomingMessage> = {}, data: Record<string, unknown> = {}) => deliver({ origin: 'https://host.example.com', source: parent, data: { protocol: 'jini.admin-surface', version: 1, kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: true, result: 'done', ...data }, ...overrides });
    return { parent, client, init, respond };
  }
  test('posts requests to the host origin learned from init, never "*"', async () => {
    const { parent, client, init, respond } = harness();
    init();
    const pending = client.call({ action: 'save', payload: { name: 'x' } });
    await Promise.resolve();
    expect(parent.posted).toEqual([{ message: { protocol: 'jini.admin-surface', version: 1, kind: 'action-request', mountId: 'nonce-1', requestId: 'r1', action: 'save', payload: { name: 'x' } }, targetOrigin: 'https://host.example.com' }]);
    respond();
    await expect(pending).resolves.toBe('done');
  });
  test('init from a window other than the parent is ignored, and a second init cannot replace the first', async () => {
    const { parent, client, init } = harness();
    init({ source: {}, origin: 'https://evil.example.com' }, { mountId: 'evil' });
    init();
    init({ origin: 'https://evil.example.com' }, { mountId: 'evil' });
    const pending = client.call({ action: 'save', payload: {} });
    await Promise.resolve();
    expect(parent.posted[0]).toMatchObject({ targetOrigin: 'https://host.example.com', message: { mountId: 'nonce-1' } });
    client.close();
    await expect(pending).rejects.toMatchObject({ code: 'closed', retryable: false });
  });
  test('responses with the wrong origin, source, mount or shape do not settle the call', async () => {
    vi.useFakeTimers();
    const { client, init, respond } = harness();
    init();
    const pending = client.call({ action: 'save', payload: {} });
    await Promise.resolve();
    respond({ origin: 'https://evil.example.com' });
    respond({ source: {} });
    respond({}, { mountId: 'nonce-2' });
    respond({}, { ok: false, error: { code: 'x' } });
    respond({}, { requestId: 'r9' });
    vi.advanceTimersByTime(1000);
    await expect(pending).rejects.toMatchObject({ name: 'AdminSurfaceCallError', code: 'timeout', retryable: true });
  });
  test('bootstrap data is withheld once expired', () => {
    const fresh = harness();
    fresh.init({}, { bootstrap: { surfaceId: 's', issuedAt: 0, expiresAt: 5_001, data: { token: 't' } } });
    expect(fresh.client.bootstrap()).toEqual({ token: 't' });
    const stale = harness();
    stale.init({}, { bootstrap: { surfaceId: 's', issuedAt: 0, expiresAt: 5_000, data: { token: 't' } } });
    expect(stale.client.bootstrap()).toBeUndefined();
  });
});

describe('bootstrap and mount', () => {
  test('bootstrap headers forbid caching', () => {
    expect(adminSurfaceBootstrapHeaders()).toEqual({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', Pragma: 'no-cache', 'X-Content-Type-Options': 'nosniff' });
  });
  test('the bootstrap expires one minute after issue, and a caller cannot lengthen that', () => {
    const bootstrap = createAdminSurfaceBootstrap({ surfaceId: 's', data: {}, nowMs: 1000 });
    expect(bootstrap).toEqual({ surfaceId: 's', issuedAt: 1000, expiresAt: 61_000, data: {} });
    expect(isAdminSurfaceBootstrapCurrent({ bootstrap, nowMs: 60_999 })).toBe(true);
    expect(isAdminSurfaceBootstrapCurrent({ bootstrap, nowMs: 61_000 })).toBe(false);
    // Malformed input on purpose: the removed ttlMs option, passed untyped, must change nothing.
    const longer = { ttlMs: 300_001 } as unknown as Record<string, never>;
    expect(createAdminSurfaceBootstrap({ surfaceId: 's', data: {}, nowMs: 0 }, longer).expiresAt).toBe(60_000);
  });
  test('each mount gets a fresh 128-bit nonce', () => {
    const a = createAdminSurfaceMount({ surfaceId: 's' });
    const b = createAdminSurfaceMount({ surfaceId: 's' });
    expect(a.mountId).toMatch(/^[0-9a-f]{32}$/);
    expect(a.mountId).not.toBe(b.mountId);
    expect(Object.keys(a).sort()).toEqual(['mountId', 'surfaceId']);
  });
});

