/** `createInstalledPackageIndex().indexInstalledRoot()` — reading one installed package's manifest and file tree. */
import { afterEach, describe, expect, it } from 'vitest';
import { mkdir, mkdtemp, realpath, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { AgentPluginInstallError } from '../../install-errors.js';
import { createInstalledPackageIndex } from '../../installed-package-index.js';
import type { AgentPluginLifecyclePorts } from '../../ports.js';
import { forceRemove } from '../fixtures/force-remove.js';
import { ports } from '../test-support.js';

const SCHEMA = 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json';
const DIGEST = 'a'.repeat(64);
const roots: string[] = [];
afterEach(async () => { for (const root of roots.splice(0)) await forceRemove(root); });

async function packageRoot(files: Record<string, string> = {}): Promise<string> {
  const root = await realpath(await mkdtemp(path.join(tmpdir(), 'jini-package-index-')));
  roots.push(root);
  for (const [relative, content] of Object.entries(files)) {
    await mkdir(path.dirname(path.join(root, relative)), { recursive: true });
    await writeFile(path.join(root, relative), content);
  }
  return root;
}
const manifest = (fields: Record<string, unknown> = {}) => JSON.stringify({ $schema: SCHEMA, name: 'my-plugin', ...fields });
const index = (root: string, host: AgentPluginLifecyclePorts = ports) => createInstalledPackageIndex({ ports: host }).indexInstalledRoot({ packageRoot: root, archiveDigest: DIGEST });

describe('indexInstalledRoot refusals', () => {
  it('reports MANIFEST_MISSING when plugin.json is absent', async () => {
    await expect(index(await packageRoot())).rejects.toMatchObject({ code: 'MANIFEST_MISSING', message: 'the archive does not contain a plugin.json at its root' });
  });

  it('propagates a plugin.json read fault other than a missing file', async () => {
    const root = await packageRoot();
    await mkdir(path.join(root, 'plugin.json'));
    await expect(index(root)).rejects.toMatchObject({ code: 'EISDIR' });
  });

  it('reports MANIFEST_INVALID with the parse error as cause for malformed JSON', async () => {
    const error = await index(await packageRoot({ 'plugin.json': '{' })).catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(AgentPluginInstallError);
    expect(error).toMatchObject({ code: 'MANIFEST_INVALID', message: 'plugin.json is not valid JSON', cause: expect.any(SyntaxError) });
  });

  it('reports MANIFEST_INVALID with the validation errors for a manifest that fails the grammar', async () => {
    await expect(index(await packageRoot({ 'plugin.json': JSON.stringify({ $schema: SCHEMA }) })))
      .rejects.toMatchObject({ code: 'MANIFEST_INVALID', message: "plugin.json failed validation: plugin.json 'name' is required and must be a string" });
  });
});

describe('indexInstalledRoot results', () => {
  it('indexes every regular file sorted and every skill sorted by name', async () => {
    const root = await packageRoot({ 'plugin.json': manifest(), 'skills/zeta/SKILL.md': '#', 'skills/alpha/SKILL.md': '#', 'skills/alpha/notes.md': '' });
    const indexed = await index(root);
    expect(indexed.files).toEqual(['plugin.json', 'skills/alpha/SKILL.md', 'skills/alpha/notes.md', 'skills/zeta/SKILL.md']);
    expect(indexed.skills).toEqual([{ name: 'alpha', skillPath: 'skills/alpha/SKILL.md' }, { name: 'zeta', skillPath: 'skills/zeta/SKILL.md' }]);
  });

  it('skips an entry that is neither a directory nor a regular file', async () => {
    const root = await packageRoot({ 'plugin.json': manifest() });
    await symlink(path.join(root, 'plugin.json'), path.join(root, 'link.json'));
    expect((await index(root)).files).toEqual(['plugin.json']);
  });

  it('omits every optional manifest field the manifest does not declare', async () => {
    expect(await index(await packageRoot({ 'plugin.json': manifest() }))).toEqual({
      pluginId: 'my-plugin', id: 'unknown/my-plugin', provides: [], version: undefined,
      archiveDigest: DIGEST, packageRoot: expect.any(String), files: ['plugin.json'], skills: [],
    });
  });

  it('carries description, keywords, author and license through', async () => {
    const indexed = await index(await packageRoot({ 'plugin.json': manifest({ description: 'd', keywords: ['k'], author: 'a', license: 'MIT' }) }));
    expect(indexed).toMatchObject({ description: 'd', keywords: ['k'], author: 'a', license: 'MIT' });
  });

  it('carries validated exports and declared old identities without reading templates', async () => {
    const definition = { template: 'exports/button.html', props: { type: 'object' }, consent: 'necessary', staticExport: 'fallback-only', version: 1 };
    const metadata = { exports: { button: definition }, renamedFrom: ['publisher/previous'] };
    const root = await packageRoot({ 'plugin.json': manifest({ extensions: { [ports.extensionNamespace]: metadata } }) });
    const indexed = await index(root);
    expect(indexed.exports).toEqual(metadata.exports);
    expect(indexed.renamedFrom).toEqual(metadata.renamedFrom);
    expect(indexed.files).toEqual(['plugin.json']);
  });

  it('refuses malformed export metadata at the shared manifest boundary', async () => {
    const root = await packageRoot({ 'plugin.json': manifest({ extensions: { [ports.extensionNamespace]: { exports: { button: {} } } } }) });
    await expect(index(root)).rejects.toMatchObject({ code: 'MANIFEST_INVALID', message: 'plugin.json failed validation: exports.button: version must be a positive safe integer' });
  });

  it('trims and caps the host displayName and summary', async () => {
    const extensions = { [ports.extensionNamespace]: { displayName: `  ${'n'.repeat(70)}  `, summary: ` ${'s'.repeat(1300)} ` } };
    const indexed = await index(await packageRoot({ 'plugin.json': manifest({ extensions }) }));
    expect([indexed.displayName, indexed.summary]).toEqual(['n'.repeat(64), 's'.repeat(1200)]);
  });

  it('ignores a non-string or blank displayName and summary', async () => {
    const extensions = { [ports.extensionNamespace]: { displayName: 7, summary: '   ' } };
    const indexed = await index(await packageRoot({ 'plugin.json': manifest({ extensions }) }));
    expect(['displayName' in indexed, 'summary' in indexed]).toEqual([false, false]);
  });

  it('reports each manifest identity warning as an event', async () => {
    const events: string[] = [];
    await index(await packageRoot({ 'plugin.json': manifest() }), { ...ports, onEvent: ({ message }) => events.push(message) });
    expect(events).toEqual(["Plugin 'my-plugin' has no publisher-qualified id; using 'unknown/my-plugin'."]);
  });
});

src/lifecycle/__tests__/unit/bundled-sou.source:
import assert from "node:assert/strict";
import { packAgentPluginDirectory } from "../test-support.js";
import { mkdir, mkdtemp, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "../legacy-test.js";

import { createBundledSourceArchiveReader } from "../test-support.js";


/**
 * @file The directory-to-archive round trip that lets a bundled package go THROUGH
 * `installAgentPlugin` rather than around it.
 *
 * The two properties that matter: the round trip is lossless (or the installer would publish
 * different bytes than the repo holds), and the digest is deterministic (or seeding would
 * re-extract on every boot instead of hitting the content-addressed dedup path).
 */

async function fixtureDir(files: Readonly<Record<string, string>>): Promise<string> {
  const dir = await mkdtemp(path.join(tmpdir(), "host-bundled-archive-"));
  for (const [relative, content] of Object.entries(files)) {
    const absolute = path.join(dir, relative);
    await mkdir(path.dirname(absolute), { recursive: true });
    await writeFile(absolute, content, "utf8");
  }
  return dir;
}

async function readBack(bytes: Uint8Array): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for await (const entry of createBundledSourceArchiveReader().entries({ archive: bytes })) {
    assert.equal(entry.kind, "file");
    if (entry.kind !== "file") continue;
    const chunks: Uint8Array[] = [];
    for await (const chunk of entry.openReadStream({})) chunks.push(chunk);
    out[entry.entryPath] = Buffer.concat(chunks.map((chunk) => Buffer.from(chunk))).toString("utf8");
  }
  return out;
}

test("packs and unpacks every file losslessly, including nested and non-ASCII content", async () => {
  const files = {
    "plugin.json": '{"name":"x"}',
    "skills/x/SKILL.md": "# X\n\nBody — with an em dash and an emoji 🧭\n",
    "skills/x/references/deep/nested.md": "nested\n",
    "empty.txt": "",
  };
  const dir = await fixtureDir(files);
  try {
    const packed = await packAgentPluginDirectory(dir);
    assert.deepEqual(await readBack(packed.bytes), files);
    assert.deepEqual([...packed.files], Object.keys(files).sort());
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("packed plugins omit tests and their fixtures while preserving runtime files and digest", async () => {
  const runtimeFiles = {
    "plugin.json": '{"name":"runtime-only"}',
    "mcp/server.mjs": "export const ready = true;",
    "skills/runtime/SKILL.md": "# Runtime skill",
    // Runtime examples remain installable even when their names include 'fixture' or 'test'.
    "skills/runtime/examples/fixture.json": '{"example":true}',
    "mcp/test-client.mjs": "export const client = {};",
    "mcp/spec.json": '{"version":1}',
  };
  const dir = await fixtureDir({
    ...runtimeFiles,
    "__tests__/plain.mjs": "test helper",
    "__tests__/fixtures/response.json": "test-only fixture",
    "mcp/__tests__/fixtures.mjs": "nested test-only fixture",
    "mcp/server.test.mjs": "test",
    "mcp/server.spec.mjs": "spec",
    "mcp/server.test.ts": "TypeScript test",
    "mcp/server.spec.js.map": "test source map",
  });
  try {
    const packed = await packAgentPluginDirectory(dir);
    assert.deepEqual([...packed.files], Object.keys(runtimeFiles).sort());
    // Check the encoded archive too: filtering only the reported file list cannot pass.
    assert.deepEqual(await readBack(packed.bytes), runtimeFiles);
    await writeFile(path.join(dir, "__tests__/plain.mjs"), "changed test helper");
    await writeFile(path.join(dir, "mcp/server.test.mjs"), "changed test");
    await writeFile(path.join(dir, "mcp/server.spec.js.map"), "changed test source map");
    const repacked = await packAgentPluginDirectory(dir);
    assert.deepEqual(repacked.bytes, packed.bytes);
    assert.equal(repacked.sha256, packed.sha256,
      "test-only edits must not republish installed runtime packages");
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("the digest is a real SHA-256 of the archive bytes and is deterministic across packs", async () => {
  const dir = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "a" });
  try {
    const first = await packAgentPluginDirectory(dir);
    const second = await packAgentPluginDirectory(dir);
    assert.match(first.sha256, /^[a-f0-9]{64}$/);
    assert.equal(first.sha256, second.sha256, "seeding relies on this to hit the content-addressed dedup path");

    const { createHash } = await import("node:crypto");
    assert.equal(createHash("sha256").update(Buffer.from(first.bytes)).digest("hex"), first.sha256);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("changing one byte of content changes the digest", async () => {
  const before = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "a" });
  const after = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "b" });
  try {
    assert.notEqual((await packAgentPluginDirectory(before)).sha256, (await packAgentPluginDirectory(after)).sha256);
  } finally {
    await rm(before, { recursive: true, force: true });
    await rm(after, { recursive: true, force: true });
  }
});

test("a symlink is skipped rather than followed — the installer would reject one anyway", async () => {
  const dir = await fixtureDir({ "plugin.json": '{"name":"x"}' });
  try {
    await symlink("/etc/passwd", path.join(dir, "sneaky"));
    const packed = await packAgentPluginDirectory(dir);
    assert.deepEqual([...packed.files], ["plugin.json"]);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("the reader refuses bytes that are not this format", async () => {
  const reader = createBundledSourceArchiveReader();
  await assert.rejects(async () => {
    for await (const _entry of reader.entries({ archive: new TextEncoder().encode("PK a real zip") })) void _entry;
  }, /bad magic/);
});

test("the reader refuses a truncated archive rather than yielding a partial file", async () => {
  const dir = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "a long enough body to truncate" });
  try {
    const packed = await packAgentPluginDirectory(dir);
    const truncated = packed.bytes.slice(0, packed.bytes.byteLength - 10);
    await assert.rejects(async () => {
      for await (const _entry of createBundledSourceArchiveReader().entries({ archive: truncated })) void _entry;
    }, /truncated entry body/);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

src/admin-surfaces/__tests__/issued-toke.source:
/**
 * @file Security pins for the per-plugin issued-token memory: one plugin's tools and its admin-surface
 * handlers run code that can share module scope (a common lib module), so a token one context
 * obtained must be withheld when the OTHER context returns or stores it, and a re-sync (new
 * generation, same cached module) must not forget it. Typed fakes; no network.
 */
import { expect, test } from 'vitest';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';
import { createIssuedTokenMemories, WITHHELD_OUTPUT_MESSAGE, type AgentPluginToolCapabilities, type IssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import type { LoadedAgentPluginTool } from '../../lifecycle/tools/definition.js';
import { createAgentPluginToolProjection } from '../../lifecycle/tools/projection.js';
import { fakeCapabilities, WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import {
  createAdminSurfaceHandlerHost, parseAdminSurfacesFile, type AdminSurfaceDescriptor, type AdminSurfaceHandlerModule,
} from '../index.js';
import { STATE_CREDENTIAL_MESSAGE } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const PLUGIN = 'acme-office';
/** Built at runtime so no credential-shaped literal is committed; distinct from the surface fake's token. */
const TOOL_TOKEN = ['tok', '-tool-', 'y'.repeat(24)].join('');

function surfaceDescriptor(): AdminSurfaceDescriptor & { readonly handlerModule: string } {
  const parsed = parseAdminSurfacesFile({ raw: JSON.stringify({ schemaVersion: 1, surfaces: [{
    id: 'settings', title: 'Settings', entry: 'surface/index.html', handlerModule: 'server/handlers.mjs', connections: [{ id: 'account' }],
    actions: [{ name: 'save', input: { type: 'object' }, result: { type: 'object' } }],
  }] }) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0] as AdminSurfaceDescriptor & { readonly handlerModule: string };
}

/** One plugin's tool and surface handler, wired the way a host composes them with ONE token memory. */
function compose(required: { readonly tool: LoadedAgentPluginTool['module']; readonly surface: AdminSurfaceHandlerModule; readonly issuedTokens: IssuedTokenMemories }) {
  const toolCapabilities: AgentPluginToolCapabilities = { ...fakeCapabilities({ tokenRequests: [], requests: [] }), connections: { getAccessToken: async () => TOOL_TOKEN } };
  const registry = createPluginContributionRegistry({});
  const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, capabilities: () => toolCapabilities, issuedTokens: required.issuedTokens });
  const loadedTool = (module: LoadedAgentPluginTool['module']): LoadedAgentPluginTool => ({ pluginId: PLUGIN, module,
    descriptor: { name: 'look', description: 'Look.', effect: 'read', module: 'tools/look.mjs', inputSchema: { type: 'object' } } });
  projection.sync({ loaded: [loadedTool(required.tool)], refusals: [] });
  const fake = createFakeSurfaceHost();
  const surfaces = createAdminSurfaceHandlerHost({ hostKind: 'hosted', capabilities: fake.port, issuedTokens: required.issuedTokens });
  surfaces.sync({ loaded: [{ pluginId: PLUGIN, descriptor: surfaceDescriptor(), module: required.surface }], refusals: [] });
  return {
    fake,
    callTool: () => { const snapshot = registry.list({})[0]!; return snapshot.tools[0]!.handler({ pluginId: PLUGIN, sdk: snapshot.sdk, auth: { access: 'admin', workspaceId: WORKSPACE_ID }, input: {} }); },
    callSurface: () => surfaces.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }).save!({ payload: {}, context: { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: PLUGIN, surfaceId: 'settings' } }),
    resyncTool: (module: LoadedAgentPluginTool['module']) => projection.sync({ loaded: [loadedTool(module)], refusals: [] }),
  };
}

test("a token the plugin's TOOL obtained is withheld when its SURFACE handler returns it", async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { ok: true }; } },
    surface: { actions: { save: async () => ({ leaked: kept }) } },
  });
  await plugin.callTool();
  await expect(plugin.callSurface()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test("a token the plugin's SURFACE handler obtained is withheld when its TOOL returns it", async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async () => ({ leaked: kept }) },
    surface: { actions: { save: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionId: 'account' }); return {}; } } },
  });
  await plugin.callSurface();
  await expect(plugin.callTool()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test("a token the plugin's TOOL obtained is never saved by its SURFACE handler's state write", async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { ok: true }; } },
    surface: { actions: { save: async ({ capabilities }) => { await capabilities.state.set({ key: 'kept', value: kept }); return {}; } } },
  });
  await plugin.callTool();
  await expect(plugin.callSurface()).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
  expect(plugin.fake.state.size).toBe(0);
});

test('a re-sync that replaces the tool generation still withholds a token the old generation obtained', async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { ok: true }; } },
    surface: { actions: { save: async () => ({}) } },
  });
  await plugin.callTool();
  plugin.resyncTool({ invoke: async () => ({ leaked: kept }) });
  await expect(plugin.callTool()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test("one plugin's memory is not another's: the same memories object keeps plugins apart", () => {
  const memories = createIssuedTokenMemories();
  memories.forPlugin({ pluginId: PLUGIN }).add(TOOL_TOKEN);
  expect([memories.forPlugin({ pluginId: PLUGIN }).has(TOOL_TOKEN), memories.forPlugin({ pluginId: 'other-plugin' }).has(TOOL_TOKEN)]).toEqual([true, false]);
});

src/lifecycle/__tests__/unit/search.unit.source:
import assert from "node:assert/strict";
import { test } from "../legacy-test.js";

import { rankInstalledAgentPlugins } from "../test-support.js";
import { type AgentPluginSearchCandidate } from "../../search.js";

/**
 * @file `rankInstalledAgentPlugins()` — pure field-weighted relevance ranking, no I/O. See
 * `search.ts`'s own header for the field-weight rationale this file proves out.
 */

function candidate(overrides: Partial<AgentPluginSearchCandidate> = {}): AgentPluginSearchCandidate {
  return {
    pluginId: "site-compliance",
    version: "1.0.0",
    description:
      "Evidence-based privacy, cookie/consent, and accessibility risk screening for a the host site.",
    keywords: ["compliance", "privacy", "gdpr", "ccpa", "cpra", "cookie", "consent", "wcag", "accessibility"],
    enabled: true,
    skills: [{ name: "site-compliance", summary: "Evidence-based privacy and accessibility risk screening." }],
    mcpServerIds: [],
    ...overrides,
  };
}

const UI_UX_DESIGN = candidate({
  pluginId: "ui-ux-design",
  version: undefined,
  description: "UI/UX design, interface-design-system, accessibility, and shadcn/ui component skills bundled as one portable Agent Plugin.",
  keywords: [], // the real bundled fixture ships none — see search.ts's own header
  enabled: false,
  skills: [
    { name: "ui-ux-design", summary: "Use when creating frontend design systems and visual direction." },
    { name: "shadcn-ui", summary: "Expert guidance for integrating and building applications with shadcn/ui components." },
  ],
});

test("an empty query returns no matches, even against real candidates — never 'list everything'", () => {
  assert.deepEqual(rankInstalledAgentPlugins("", [candidate(), UI_UX_DESIGN], 10), []);
  assert.deepEqual(rankInstalledAgentPlugins("   ", [candidate(), UI_UX_DESIGN], 10), []);
});

test("no candidates always returns no matches, regardless of query", () => {
  assert.deepEqual(rankInstalledAgentPlugins("compliance", [], 10), []);
});

test("a query matching nothing in any field returns no matches, not the full candidate list", () => {
  assert.deepEqual(rankInstalledAgentPlugins("zzz-nonexistent-term-zzz", [candidate(), UI_UX_DESIGN], 10), []);
});

test("an exact keyword match scores, even when the term appears nowhere else", () => {
  const matches = rankInstalledAgentPlugins("gdpr", [candidate(), UI_UX_DESIGN], 10);
  assert.equal(matches.length, 1);
  assert.equal(matches[0]?.pluginId, "site-compliance");
  assert.ok(matches[0]!.score > 0);
});

test("a plugin id substring match scores even with no keywords and no description hit", () => {
  const matches = rankInstalledAgentPlugins("compliance", [candidate(), UI_UX_DESIGN], 10);
  // "compliance" matches site-compliance's id AND its keywords AND its description — must still be
  // exactly one match for that one candidate, not double-counted into two rows.
  assert.equal(matches.length, 1);
  assert.equal(matches[0]?.pluginId, "site-compliance");
});

test("a plugin with NO keywords at all (the real ui-ux-design shape) is still findable via id/description/skills", () => {
  const matches = rankInstalledAgentPlugins("shadcn", [candidate(), UI_UX_DESIGN], 10);
  assert.equal(matches.length, 1);
  assert.equal(matches[0]?.pluginId, "ui-ux-design", "must be found via its shadcn-ui skill's own summary, despite zero keywords");
});

test("an id/keyword match outranks a same-term match that only appears in a skill summary", () => {
  const idMatch = candidate({ pluginId: "gdpr-helper", keywords: [], description: undefined, skills: [] });
  const skillOnlyMatch = candidate({
    pluginId: "unrelated-tool",
    keywords: [],
    description: undefined,
    skills: [{ name: "misc", summary: "mentions gdpr once, deep in a skill summary" }],
  });
  const matches = rankInstalledAgentPlugins("gdpr", [skillOnlyMatch, idMatch], 10);
  assert.equal(matches.length, 2);
  assert.equal(matches[0]?.pluginId, "gdpr-helper", "an id hit must outrank a skill-summary-only hit");
  assert.ok((matches[0]?.score ?? 0) > (matches[1]?.score ?? 0));
});

test("a multi-word query scores cumulatively across terms, not just the first term matched", () => {
  const single = rankInstalledAgentPlugins("gdpr", [candidate()], 10)[0]?.score ?? 0;
  const multi = rankInstalledAgentPlugins("gdpr cookie consent", [candidate()], 10)[0]?.score ?? 0;
  assert.ok(multi > single, "matching three terms must score higher than matching one");
});

test("results are sorted by score descending", () => {
  const strongMatch = candidate({ pluginId: "gdpr-tool", keywords: ["gdpr"] });
  const weakMatch = candidate({ pluginId: "other-tool", keywords: [], description: "mentions gdpr once", skills: [] });
  const matches = rankInstalledAgentPlugins("gdpr", [weakMatch, strongMatch], 10);
  assert.deepEqual(
    matches.map((m) => m.pluginId),
    ["gdpr-tool", "other-tool"],
  );
});

test("limit truncates the result set to the requested size", () => {
  const many = Array.from({ length: 5 }, (_, i) => candidate({ pluginId: `gdpr-tool-${i}`, keywords: ["gdpr"] }));
  const matches = rankInstalledAgentPlugins("gdpr", many, 2);
  assert.equal(matches.length, 2);
});

test("a disabled plugin still ranks and is returned — search is not gated on activation", () => {
  const matches = rankInstalledAgentPlugins("shadcn", [UI_UX_DESIGN], 10);
  assert.equal(matches.length, 1);
  assert.equal(matches[0]?.enabled, false);
});

test("every field of the source candidate is carried through onto the match, plus a score", () => {
  const [match] = rankInstalledAgentPlugins("gdpr", [candidate()], 10);
  assert.ok(match);
  assert.equal(match.pluginId, "site-compliance");
  assert.equal(match.version, "1.0.0");
  assert.equal(match.enabled, true);
  assert.deepEqual(match.mcpServerIds, []);
  assert.equal(typeof match.score, "number");
});

test("a candidate with no description and no mcp servers does not throw — every optional field is genuinely optional", () => {
  const bare: AgentPluginSearchCandidate = {
    pluginId: "bare-plugin",
    keywords: [],
    enabled: true,
    skills: [],
    mcpServerIds: [],
  };
  assert.deepEqual(rankInstalledAgentPlugins("bare", [bare], 10).map((m) => m.pluginId), ["bare-plugin"]);
  assert.deepEqual(rankInstalledAgentPlugins("anything-else", [bare], 10), []);
});

src/lifecycle/__tests__/unit/seed-bundle.source:
import { afterEach, describe, expect, test } from 'vitest';
import * as fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createAgentPluginLayout } from '../../layout.js';
import { createSeedBundledModule } from '../../seed-bundled.js';
import { BUNDLED_DIGESTS_FILENAME } from '../../bundled-digests.js';
import { ACTIVATIONS_FILENAME } from '../../activation.js';
import type { AgentPluginLifecyclePorts, FilesystemPort } from '../../ports.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

/**
 * @file `seedBundledAgentPlugins` never throws: source discovery skips non-packages, and migration,
 * activation, per-plugin and ledger faults — including non-Error throws from an injected port —
 * become report entries.
 */

const temporaries: string[] = [];
afterEach(async () => { for (const dir of temporaries.splice(0)) await forceRemove(dir); });
async function tempDir(): Promise<string> {
  const dir = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'seed-edges-')));
  temporaries.push(dir);
  return dir;
}
async function sourceWithPlugin(): Promise<string> {
  const source = await tempDir();
  await fs.mkdir(path.join(source, 'seeded-one', 'skills', 'seeded-one'), { recursive: true });
  await fs.writeFile(path.join(source, 'seeded-one', 'plugin.json'), JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'seeded-one' }));
  await fs.writeFile(path.join(source, 'seeded-one', 'skills', 'seeded-one', 'SKILL.md'), '# Seeded\n');
  return source;
}
async function seed(sourceRoot: string, overrides: Partial<AgentPluginLifecyclePorts> = {}) {
  const layout = createAgentPluginLayout({ root: await tempDir() });
  const { seedBundledAgentPlugins } = createSeedBundledModule({ ...ports, layout, onEvent: () => undefined, ...overrides });
  return { layout, report: await seedBundledAgentPlugins({ layout, workspaceId: 'ws', sourceRoot }) };
}
function failingFs(match: (target: string) => boolean, thrown: unknown, method: 'open' | 'readdir'): FilesystemPort {
  const original = fs[method] as (...args: unknown[]) => Promise<unknown>;
  return { ...fs, [method]: async (target: string, ...rest: unknown[]) => {
    if (match(String(target))) throw thrown;
    return original(target, ...rest);
  } } as FilesystemPort;
}

describe('source discovery', () => {
  test('a missing source root seeds nothing', async () => {
    const { report } = await seed(path.join(await tempDir(), 'absent'));
    expect(report.outcomes).toEqual([]);
  });
  test('stray files and directories without plugin.json are skipped silently', async () => {
    const source = await sourceWithPlugin();
    await fs.writeFile(path.join(source, 'README.md'), '# not a plugin');
    await fs.mkdir(path.join(source, 'scratch'));
    const { report } = await seed(source);
    expect(report.outcomes.map(outcome => [outcome.pluginId, outcome.status])).toEqual([['seeded-one', 'seeded']]);
    expect(report.ledgerFailure).toBeUndefined();
  });
});

describe('faults become report entries', () => {
  test('a non-Error thrown by the host migration port fails every plugin with its text', async () => {
    const source = await sourceWithPlugin();
    const { report } = await seed(source, { migrateBeforeSeed: async () => { throw 'migration port offline'; } });
    expect(report).toEqual({ sourceRoot: source, outcomes: [{ pluginId: 'seeded-one', status: 'failed', reason: 'migration port offline' }], retirements: [] });
  });
  test('a non-Error activation-lock fault fails every plugin before any install', async () => {
    const source = await sourceWithPlugin();
    const { layout, report } = await seed(source, { filesystem: failingFs(target => target.endsWith(`${ACTIVATIONS_FILENAME}.lock`), 'lock device gone', 'open') });
    expect(report.outcomes).toEqual([{ pluginId: 'seeded-one', status: 'failed', reason: 'lock device gone' }]);
    await expect(fs.stat(layout.forWorkspace({ workspaceId: 'ws' }).pluginRootDir({ pluginId: 'seeded-one' }))).rejects.toMatchObject({ code: 'ENOENT' });
  });
  test('a non-Error while packing one plugin fails only that plugin', async () => {
    const source = await sourceWithPlugin();
    const { report } = await seed(source, { filesystem: failingFs(target => target.endsWith(`${path.sep}seeded-one`), 'unreadable source', 'readdir') });
    expect(report.outcomes).toEqual([{ pluginId: 'seeded-one', status: 'failed', reason: 'unreadable source' }]);
  });
  test('a ledger write fault is reported while the seeded plugin stays seeded', async () => {
    const source = await sourceWithPlugin();
    const { report } = await seed(source, { filesystem: failingFs(target => target.includes(`${BUNDLED_DIGESTS_FILENAME}.tmp-`), new Error('ledger disk full'), 'open') });
    expect(report.outcomes.map(outcome => outcome.status)).toEqual(['seeded']);
    expect(report.ledgerFailure).toBe('ledger disk full');
  });
  test('a non-Error ledger write fault is rendered as text', async () => {
    const source = await sourceWithPlugin();
    const { report } = await seed(source, { filesystem: failingFs(target => target.includes(`${BUNDLED_DIGESTS_FILENAME}.tmp-`), 'ledger offline', 'open') });
    expect(report.ledgerFailure).toBe('ledger offline');
  });
  test('an unreadable activations file fails every plugin with the activation error message', async () => {
    const source = await sourceWithPlugin();
    const layout = createAgentPluginLayout({ root: await tempDir() });
    const workspaceRoot = layout.forWorkspace({ workspaceId: 'ws' }).root;
    await fs.mkdir(path.join(workspaceRoot, ACTIVATIONS_FILENAME), { recursive: true });
    const { seedBundledAgentPlugins } = createSeedBundledModule({ ...ports, layout, onEvent: () => undefined });
    const report = await seedBundledAgentPlugins({ layout, workspaceId: 'ws', sourceRoot: source });
    expect(report.outcomes).toHaveLength(1);
    expect(report.outcomes[0]).toMatchObject({ pluginId: 'seeded-one', status: 'failed' });
    expect((report.outcomes[0] as { reason: string }).reason).toContain(`${ACTIVATIONS_FILENAME} could not be read (EISDIR`);
  });
});

