import { test, expect } from 'vitest';
import { mkdtemp, readFile, readdir } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { createAgentPluginLifecycle, createAgentPluginLayout, AgentPluginInstallError, type AgentPluginArchiveReaderPort } from '../../index.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

// Generalized URL pipeline assertions use injected transport/archive ports and actual disk I/O.
test('pinned URL install verifies the independent digest, TOFU is labelled, and bad pins never extract', async () => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'plugin-url-install-'));
  const layout = createAgentPluginLayout({ root });
  const bytes = Buffer.from('archive-bytes');
  // An install iterates entries twice (a metadata-only limits pass, then extraction), so an
  // extraction is counted when the manifest's content is read, not when entries is called.
  let readerCalls = 0;
  let extractions = 0;
  const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
    readerCalls++;
    for (const [entryPath, text] of Object.entries({
      'plugin.json': JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'fixture' }),
      'skills/fixture/SKILL.md': '# Exact installed guidance\n',
    })) yield { kind: 'file', entryPath, declaredSize: Buffer.byteLength(text), openReadStream: async function* () {
      if (entryPath === 'plugin.json') extractions++;
      yield Buffer.from(text);
    } };
  } };
  const api = createAgentPluginLifecycle({ ...ports, layout, fetch: async () => new Response(bytes), outboundGuard: { assertAllowed: async () => {} } });
  const input = { url: 'https://example.com/package.zip', layout, workspaceId: 'workspace-a', archiveReader };
  try {
    await expect(api.installAgentPluginFromUrl({ ...input, integrity: { kind: 'pinned', sha256: '0'.repeat(64) } })).rejects.toBeInstanceOf(AgentPluginInstallError);
    expect(readerCalls).toBe(0);
    expect(await readdir(root)).toEqual([]);
    const sha256 = createHash('sha256').update(bytes).digest('hex');
    const pinned = await api.installAgentPluginFromUrl({ ...input, integrity: { kind: 'pinned', sha256 } });
    expect(pinned.digestWasPinned).toBe(true);
    expect(await readFile(path.join(pinned.installed.packageRoot, 'skills/fixture/SKILL.md'), 'utf8')).toBe('# Exact installed guidance\n');
    const tofu = await api.installAgentPluginFromUrl({ ...input, integrity: { kind: 'trust-on-first-use' } });
    expect(tofu.digestWasPinned).toBe(false);
    expect(tofu.sha256).toBe(sha256);
    // Layout B identifies the plugin on each install, then reuses its published digest tree.
    expect(extractions).toBe(2);
    expect(readerCalls).toBe(4);
    expect(tofu.installed).toEqual(pinned.installed);
  } finally { await forceRemove(root); }
});

src/lifecycle/tools/__tests__/agent-plug.source:
/**
 * @file The one vertical-slice proof: a real installed, bundled, active plugin ships a host-named
 * tool file and an `.mjs` module; the trusted loader imports it, the projection registers it in a
 * real ToolRegistry under `p_<plugin>__<local>`, and a call runs with injected fake capabilities.
 */
import { expect, test } from 'vitest';
import { createHarness, FAKE_TOKEN, installPlugin, toolsFile, TOOLS_FILENAME, withWorkspace } from './support.js';

const APPEND_MODULE = `export default {
  async invoke({ input, capabilities }) {
    const token = await capabilities.connections.getAccessToken({ connectionRef: input.connectionRef });
    const response = await capabilities.http.fetch({ url: 'https://api.example.test/tables/' + input.table + '/rows' },
      { method: 'POST', headers: { authorization: 'Bearer ' + token }, body: JSON.stringify({ values: input.values }) });
    return { status: response.status, appended: input.values.length };
  },
  describeAffectedResources({ input }) { return ['table ' + input.table]; },
};
`;

test('load a fake plugin .mjs tool, project it, invoke it with injected capabilities and get its result', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'acme-office', files: {
      [TOOLS_FILENAME]: toolsFile([{ name: 'append_rows', description: 'Append rows to a table.', effect: 'write', module: 'tools/append-rows.mjs',
        inputSchema: { type: 'object', required: ['connectionRef', 'table', 'values'], additionalProperties: false, properties: {
          connectionRef: { type: 'string' }, table: { type: 'string' }, values: { type: 'array', items: { type: 'string' } } } } }]),
      'tools/append-rows.mjs': APPEND_MODULE,
    } });
    const harness = createHarness();

    expect(await harness.refresh()).toEqual([]);
    expect(harness.tools.has({ toolId: 'p_acme_office__append_rows' })).toBe(true);
    const input = { connectionRef: 'conn-1', table: 'leads', values: ['a', 'b'] };
    expect(await harness.projection.describeAffectedResources({ toolId: 'p_acme_office__append_rows', input })).toEqual({ effect: 'write', resources: ['table leads'] });

    expect(await harness.invoke('p_acme_office__append_rows', input)).toEqual({ status: 200, appended: 2 });
    expect(harness.log.tokenRequests).toEqual(['conn-1']);
    expect(harness.log.requests).toEqual([{ url: 'https://api.example.test/tables/leads/rows',
      headers: { authorization: `Bearer ${FAKE_TOKEN}` }, body: '{"values":["a","b"]}' }]);
  });
});

